/* index.js — renders the home page from window.CATALOGUE (generated by build.py).
   A plain table: one row per problem; problems with several approaches show
   one line per approach in the Pattern, Data structure and Guide columns. */
(function () {
  "use strict";
  const C = window.CATALOGUE, S = C.site || {}, esc = VIZ.esc;
  const app = document.getElementById("app");
  const DIFF = { Easy: 1, Medium: 2, Hard: 3 };
  let sortKey = "id", sortDir = 1;
  const F = { diff: "", pattern: "", ds: "", c: false };
  const uniq = (xs) => [...new Set(xs)].sort((a, b) => a.localeCompare(b));
  const allA = C.problems.flatMap((p) => p.approaches);
  const PATTERNS = uniq(allA.map((a) => a.pattern));
  const DSS = uniq(allA.flatMap((a) => a.ds));
  const DIFFS = ["Easy", "Medium", "Hard"].filter((d) => C.problems.some((p) => p.difficulty === d));
  const opts = (xs) => xs.map((x) => `<option value="${esc(x)}">${esc(x)}</option>`).join("");

  const links = [];
  if (S.notionPatterns) links.push(`<a href="${esc(S.notionPatterns)}" target="_blank" rel="noopener">Pattern guides (Notion) ↗</a>`);
  if (S.leetcodeProfile) links.push(`<a href="${esc(S.leetcodeProfile)}" target="_blank" rel="noopener">Accepted solutions on LeetCode ↗</a>`);
  if (S.repoUrl) links.push(`<a href="${esc(S.repoUrl)}" target="_blank" rel="noopener">Source on GitHub ↗</a>`);

  const COLS = [
    ["id", "#"], ["title", "Problem"], ["difficulty", "Difficulty"], ["pattern", "Pattern"], ["ds", "Data structure"], [null, "Guide"],
  ];
  app.innerHTML = `
    <header class="vz-header"><h1>${esc(S.title || "Pattern Visualiser")}</h1></header>
    <p>${esc(S.intro || "")}</p>
    <div class="vz-meta">${links.join("")}</div>
    <div class="ix-filters" role="group" aria-label="Filters">
      <label>Difficulty <select id="f-diff"><option value="">All</option>${opts(DIFFS)}</select></label>
      <label>Pattern <select id="f-pattern"><option value="">All</option>${opts(PATTERNS)}</select></label>
      <label>Data structure <select id="f-ds"><option value="">All</option>${opts(DSS)}</select></label>
      <label><input type="checkbox" id="f-c"> has a C version</label>
      <button id="f-reset" hidden>Clear filters</button>
    </div>
    <div class="ix-wrap"><table class="ix-table"><thead><tr>${COLS.map(([k, t]) =>
      k ? `<th aria-sort="none" data-k="${k}"><button>${t}</button></th>` : `<th>${t}</th>`).join("")}</tr></thead>
      <tbody id="ix-body"></tbody></table></div>
    <section id="ix-articles" hidden><h2 class="vz-sub">Articles</h2><ul id="ix-articles-list"></ul></section>
    <footer class="vz-footer" id="ix-footer"></footer>`;

  const guide = (pattern) => (S.patternGuides || {})[pattern] || S.notionPatterns || "";
  const idNum = (p) => (/^\d+$/.test(p.source.id || "") ? +p.source.id : Infinity);
  const val = {
    id: (p) => [p.source.site || "", idNum(p), p.title],
    title: (p) => p.title.toLowerCase(),
    difficulty: (p) => DIFF[p.difficulty] || 9,
    pattern: (p) => p.approaches[0].pattern.toLowerCase(),
    ds: (p) => (p.approaches[0].ds[0] || "").toLowerCase(),
  };
  const cmp = (x, y) => {
    if (Array.isArray(x)) { for (let i = 0; i < x.length; i++) { const c = cmp(x[i], y[i]); if (c) return c; } return 0; }
    return x < y ? -1 : x > y ? 1 : 0;
  };

  function render() {
    document.querySelectorAll("th[data-k]").forEach((th) =>
      th.setAttribute("aria-sort", th.dataset.k === sortKey ? (sortDir > 0 ? "ascending" : "descending") : "none"));
    const match = (a) => (!F.pattern || a.pattern === F.pattern) && (!F.ds || a.ds.includes(F.ds)) && (!F.c || a.hasC);
    const visible = C.problems
      .filter((p) => !F.diff || p.difficulty === F.diff)
      .map((p) => ({ ...p, all: p.approaches.length, approaches: p.approaches.filter(match) }))
      .filter((p) => p.approaches.length);
    document.getElementById("f-reset").hidden = !(F.diff || F.pattern || F.ds || F.c);
    const n = C.problems.length, shown = visible.length;
    const cnt = document.getElementById("ix-count");
    if (cnt) cnt.textContent = shown === n ? `${n} problem${n === 1 ? "" : "s"}` : `${shown} of ${n} problems`;
    const rows = visible.sort((a, b) => sortDir * cmp(val[sortKey](a), val[sortKey](b)) || cmp(val.id(a), val.id(b)));
    document.getElementById("ix-body").innerHTML = rows.map((p) => {
      const many = p.all > 1;
      const href = (a) => esc(p.file) + (many ? "#" + esc(a.id) : "");
      const lines = (f) => p.approaches.map((a) => `<div>${f(a)}</div>`).join("");
      return `<tr>
        <td class="id">${esc(p.label || "")}</td>
        <td><a href="${esc(p.file)}">${esc(p.title)}</a></td>
        <td><span class="pill ${esc(p.difficulty.toLowerCase())}">${esc(p.difficulty)}</span></td>
        <td>${lines((a) => `<a href="${href(a)}">${esc(a.pattern)}</a>`)}</td>
        <td>${lines((a) => esc(a.ds.join(", ")))}</td>
        <td>${lines((a) => guide(a.pattern) ? `<a href="${esc(guide(a.pattern))}" target="_blank" rel="noopener">guide ↗</a>` : "")}</td>
      </tr>`;
    }).join("") || `<tr><td colspan="6" class="note">Nothing matches these filters.</td></tr>`;
  }

  const bind = (id, key, prop) => document.getElementById(id).addEventListener("change", (e) => { F[key] = e.target[prop]; render(); });
  bind("f-diff", "diff", "value");
  bind("f-pattern", "pattern", "value");
  bind("f-ds", "ds", "value");
  bind("f-c", "c", "checked");
  document.getElementById("f-reset").addEventListener("click", () => {
    Object.assign(F, { diff: "", pattern: "", ds: "", c: false });
    ["f-diff", "f-pattern", "f-ds"].forEach((id) => (document.getElementById(id).value = ""));
    document.getElementById("f-c").checked = false;
    render();
  });

  document.querySelector(".ix-table thead").addEventListener("click", (e) => {
    const th = e.target.closest("th[data-k]");
    if (!th) return;
    if (sortKey === th.dataset.k) sortDir = -sortDir;
    else { sortKey = th.dataset.k; sortDir = 1; }
    render();
  });

  if (C.articles && C.articles.length) {
    document.getElementById("ix-articles").hidden = false;
    document.getElementById("ix-articles-list").innerHTML = C.articles.map((a) =>
      `<li><a href="${esc(a.url)}" target="_blank" rel="noopener">${esc(a.title)} ↗</a></li>`).join("");
  }

  const foot = [`<span id="ix-count"></span>`];
  if (S.bigO) foot.push(`<a href="${esc(S.bigO)}" target="_blank" rel="noopener">Big-O reference ↗</a>`);
  if (S.repoUrl) foot.push(`<a class="easter" href="${esc(S.repoUrl)}/tree/main/ai-panic" target="_blank" rel="noopener" title="Things the AI worried about. Most of them never happened.">ai-panic</a>`);
  document.getElementById("ix-footer").innerHTML = foot.join("");
  render();
})();
